mapper.select:
select * from ( SELECT rj.JOB_ID jobId , rj.JOB_NAME jobName , rj.LOOP_DATE_DETAIL loopDateDetail, rj.START_DATE startDate, rj.END_DATE endDate, rj.LOOP_DATE_VALUE as loopDateValue, P.START_DATE as execDate FROM rep_job rj LEFT JOIN ( select T.JOB_ID, T.START_DATE, T.Sequence from ( select @rownum:=@rownum+1 'rownum', a.JOB_ID,a.START_DATE, if(@JOB_ID=a.JOB_ID,@rank:=@rank+1,@rank:=1) as Sequence, @JOB_ID:=a.JOB_ID from(SELECT * from (select * from REP_INSTALL_LOG where START_DATE is not null)c order by JOB_ID,START_DATE DESC)a, (select @rownum:=0,@JOB_ID:=null,@rank:=0)b
)T where T.Sequence<=1 ) P ON P.JOB_ID=rj.JOB_ID WHERE 1=1
AND rj.JOB_NAME LIKE CONCAT('%',CONCAT(#{jobName,jdbcType=VARCHAR},'%'))
AND rj.JOB_ID IN
#{item}
ORDER BY rj.UPDATE_TIME desc ) tmp where 1=1

mapper.update:
      update REP_REVEAL
      set 
      CONFIRM_STATUS = #{confirmStatus,jdbcType=VARCHAR}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = NOW()
      where 1=1
      and id = #{id,jdbcType=VARCHAR}
